import{_ as r,E as i,h as n,c as o,b as a,f as s,H as d,a4 as l}from"./chunks/framework.B_fYP6Of.js";const f=JSON.parse('{"title":"ADR 002 · Retrieval storage","description":"An architecture decision record on evaluating SQLite for hybrid retrieval, including the workload, eligibility filters, and recovery tests that should drive selection.","frontmatter":{"title":"ADR 002 · Retrieval storage","description":"An architecture decision record on evaluating SQLite for hybrid retrieval, including the workload, eligibility filters, and recovery tests that should drive selection.","teaser":"A single database can simplify deployment. The test is whether it still returns the right permitted passage while another document is being indexed."},"headers":[],"relativePath":"decisions/002-retrieval-storage.md","filePath":"decisions/002-retrieval-storage.md"}'),c={name:"decisions/002-retrieval-storage.md"};function h(p,e,u,v,g,m){const t=i("LabArticleHeader");return n(),o("div",null,[e[0]||(e[0]=a("h1",{id:"adr-002-·-retrieval-storage",tabindex:"-1"},[s("ADR 002 · Retrieval storage "),a("a",{class:"header-anchor",href:"#adr-002-·-retrieval-storage","aria-label":'Permalink to "ADR 002 · Retrieval storage"'},"​")],-1)),d(t),e[1]||(e[1]=l('<p><em>Architecture decision record · Storage selection under evaluation.</em></p><p>The candidate is a local SQLite database that holds text, vectors, and relationships. The decision depends on a representative workload and on what happens to search when the index changes.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>One reader searches by a case number. Another describes the same case in their own words. A third follows a relationship to a source. Compare BM25, vector similarity, and bounded graph retrieval on all three. Corpus size, update rate, and required concurrency still need to be specified.</p><h2 id="candidate-design" tabindex="-1">Candidate design <a class="header-anchor" href="#candidate-design" aria-label="Permalink to &quot;Candidate design&quot;">​</a></h2><p>Co-locate SQLite retrieval with a Rust service. Use ordinary tables for source revisions, chunks, identities, claims, and provenance; FTS5 for BM25; an evaluated vector extension; and indexed relationships for bounded graph traversal.</p><p>Expose vector/search capabilities explicitly. Preserve canonical IDs and evidence contracts so a dedicated vector or search service can replace an adapter without changing answer policy.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><p>A dedicated service offers different indexing, filtering, replication, and scaling choices. A mixed deployment could keep canonical metadata in SQLite and move one measured bottleneck. Run the comparison at equivalent retrieval quality and permitted scope. Otherwise a faster result may simply reflect a different question.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Standard SQLite WAL has one writer per database and same-host sharing requirements. The deployment needs a local index-publication owner, short transactions, bounded database work, checkpoint policy, and an explicit backup/recovery design. Multiple hosts need evaluated ownership and replication behavior. Broker events are notifications, not file replication.</p><h2 id="selection-gates" tabindex="-1">Selection gates <a class="header-anchor" href="#selection-gates" aria-label="Permalink to &quot;Selection gates&quot;">​</a></h2><p>Test filtered recall and latency, exact-versus-ANN behavior, simultaneous ingestion and chat, graph fanout, memory, crash recovery, extension migrations, and source-version consistency. Pin and validate the extension&#39;s native build and transactional behavior. See <a href="/knowledge-lab/architecture/retrieval">hybrid retrieval</a>.</p>',13))])}const x=r(c,[["render",h]]);export{f as __pageData,x as default};
